#!/usr/bin/env python3
"""Checkout-local provisioning and read-only diagnosis. No remote configuration."""
import json
import os
from pathlib import Path
import re
import shutil
import subprocess
import sys
from service_setup import OVERRIDES

try:
    import tomllib
except ImportError:
    sys.exit("setup: Python 3.11+ is required")

ROOT = Path(__file__).resolve().parent.parent
VERSION_PROBES = {
    'actionlint': ['actionlint', '-version'],
    'go': ['go', 'version'],
    'rust': ['rustc', '--version'],
}


FACT_LISTS = ("commands", "deployments", "backendFolders", "services", "plugins", "productRules")
# A product plugin is product code. It can never be one of the folders agents load instructions from.
AGENT_FOLDERS = (".claude", ".codex", ".gemini", ".cursor", ".agents", ".github")
CONVEX_GUIDELINES = "_generated/ai/guidelines.md"


def read_config(path):
    return check_config(json.loads(Path(path).read_text()))


def fact_text(value, name, limit=160):
    if not isinstance(value, str) or not value.strip() or "\n" in value or len(value) > limit:
        raise ValueError(f"facts.{name} must be one line of at most {limit} characters")


def fact_path(value, name):
    if (not isinstance(value, str) or not value.strip("./") or Path(value).is_absolute()
            or ".." in Path(value).parts):
        raise ValueError(f"facts.{name} must contain checkout-relative paths")
    return value.removeprefix("./").rstrip("/")


def fact_records(facts, key, required, optional=()):
    for index, record in enumerate(facts[key]):
        name = f"{key}[{index}]"
        if (not isinstance(record, dict) or not set(required) <= set(record)
                or set(record) - set(required) - set(optional)):
            raise ValueError(f"facts.{name} requires {', '.join(required)}"
                             + (f" and accepts {', '.join(optional)}" if optional else ""))
        for field, value in record.items():
            fact_text(value, f"{name}.{field}")


def check_facts(config):
    """Facts are data rendered into AGENTS.md. They never carry workflow rules."""
    facts = config["facts"]
    allowed = {"summary", *FACT_LISTS, "convex", "coderabbitProfile"}
    if set(facts) - allowed:
        raise ValueError("Unknown facts: " + ", ".join(sorted(set(facts) - allowed)))
    fact_text(facts.get("summary"), "summary")
    for key in FACT_LISTS:
        if not isinstance(facts.get(key), list):
            raise ValueError(f"facts.{key} must be an explicit list")
    fact_records(facts, "commands", ("command", "purpose"))
    fact_records(facts, "deployments", ("name", "service", "environment", "trigger"), ("url",))
    fact_records(facts, "services", ("name", "purpose"))
    for key in ("backendFolders", "plugins"):
        facts[key] = [fact_path(value, key) for value in facts[key]]
    for name in facts["plugins"]:
        if set(Path(name).parts) & set(AGENT_FOLDERS) or Path(name).parts[:2] in (("docs", "agents"), ("docs", "adr")):
            raise ValueError("facts.plugins lists shipped product plugins, never an agent or instruction folder: " + name)
    for index, rule in enumerate(facts["productRules"]):
        if not isinstance(rule, dict) or set(rule) != {"doc", "check"}:
            raise ValueError(f"facts.productRules[{index}] requires doc and check")
        rule["doc"] = fact_path(rule["doc"], "productRules")
        if rule["check"] not in config["validation"]:
            raise ValueError("facts.productRules check must be one of the validation commands, "
                             "so ./scripts/check and CI enforce it: " + rule["doc"])
    if ("convex" in facts) != ("convex" in config["development"]):
        raise ValueError("facts.convex and development.convex must be declared together")
    if "convex" in facts:
        convex = facts["convex"]
        if not isinstance(convex, dict) or set(convex) != {"guidelines"}:
            raise ValueError("facts.convex requires the guidelines file path")
        convex["guidelines"] = fact_path(convex["guidelines"], "convex.guidelines")
        if not convex["guidelines"].endswith("/" + CONVEX_GUIDELINES):
            raise ValueError("facts.convex.guidelines must be the Convex-maintained <functions>/" + CONVEX_GUIDELINES)
    profile = facts.get("coderabbitProfile")
    if config["review"].get("coderabbit") or profile is not None:
        if not isinstance(profile, str) or not re.fullmatch(r"[a-z0-9][a-z0-9-]*", profile):
            raise ValueError("facts.coderabbitProfile must name the CodeRabbit profile for this repository")


def check_config(config):
    if not isinstance(config, dict) or config.get("version") != 3:
        raise ValueError("Use configuration version 3; see docs/setup.md in sshickles/repo-standard for migration")
    if "conventions" in config:
        raise ValueError("Remove conventions; work arrives as T3 prompts and branch names are free")
    for key in ("repository", "profile", "git", "validation", "integrations", "review", "development", "facts", "ciChecks", "testCommand"):
        if key not in config:
            raise ValueError(f"Missing required configuration: {key}")
    for key in ("git", "integrations", "review", "development", "facts"):
        if not isinstance(config[key], dict):
            raise ValueError(f"{key} must be an object")
    if not isinstance(config["repository"], str) or not re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9-]*/[A-Za-z0-9][A-Za-z0-9_.-]*", config["repository"]):
        raise ValueError("repository must be OWNER/REPO")
    if config["profile"] not in ("nextjs", "custom"):
        raise ValueError("profile must be nextjs or custom (existing/custom template stack)")
    git = config["git"]
    if not re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9_-]*", git.get("remote", "")):
        raise ValueError("git.remote must be an explicit remote name")
    branch = git.get("baseBranch", "")
    if not branch or branch.startswith("-") or subprocess.run(
        ["git", "check-ref-format", "--branch", branch], capture_output=True).returncode:
        raise ValueError("git.baseBranch must be a valid branch")
    if not isinstance(config["validation"], list) or not config["validation"]:
        raise ValueError("validation requires at least one finite local command")
    dev = config["development"]
    if dev.get("environment") not in ("none", "development", "preview", "production"):
        raise ValueError("development.environment must name a documented service environment")
    if "vercel" in dev:
        vercel = dev['vercel']
        if (not isinstance(vercel, dict) or vercel.get('environment') != 'development'
                or set(vercel) - {'environment', 'projectId', 'orgId', 'requiredKeys'}
                or not isinstance(vercel.get('projectId'), str) or not vercel['projectId'].strip()):
            raise ValueError('development.vercel requires environment: development and an explicit projectId')
        if not isinstance(vercel.get('orgId'), str) or not vercel['orgId'].strip():
            raise ValueError('development.vercel.orgId must be a nonempty organization or team ID')
        required_keys = vercel.get('requiredKeys', [])
        if not isinstance(required_keys, list) or any(
                not isinstance(key, str) or not re.fullmatch(r'[A-Za-z_][A-Za-z0-9_]*', key)
                for key in required_keys):
            raise ValueError('development.vercel.requiredKeys must be a list of environment variable names')
    if 'vercel' in dev and dev['environment'] != 'development':
        raise ValueError('development.vercel requires development.environment: development')
    if "convex" in dev:
        convex = dev["convex"]
        if (not isinstance(convex, dict) or not {"deployment"} <= set(convex)
                or set(convex) - {"deployment", "urlVariable", "url", "additionalDeployments"}
                or not isinstance(convex["deployment"], str)
                or not re.fullmatch(r"dev:[a-z0-9]+(?:-[a-z0-9]+)+", convex["deployment"])):
            raise ValueError("development.convex requires an explicit dev deployment and optional urlVariable")
        if "urlVariable" in convex and (not isinstance(convex["urlVariable"], str)
                or not re.fullmatch(r"[A-Z_][A-Z0-9_]*CONVEX_URL|CONVEX_URL", convex["urlVariable"])):
            raise ValueError("development.convex.urlVariable must name a Convex URL variable")
        if 'url' in convex and (not isinstance(convex['url'], str) or not re.fullmatch(
                'https://' + re.escape(convex['deployment'][4:]) + r'(?:\.[a-z0-9-]+)?\.convex\.cloud', convex['url'])):
            raise ValueError('development.convex.url must be the configured deployment cloud URL')
        if "vercel" not in dev or dev["environment"] != "development":
            raise ValueError("Convex setup requires development.environment: development and development.vercel")
        additional = convex.get('additionalDeployments', {})
        if not isinstance(additional, dict):
            raise ValueError('development.convex.additionalDeployments must be a named deployment object')
        variables = {'CONVEX_DEPLOYMENT', *OVERRIDES, convex.get('urlVariable')}
        for name, target in additional.items():
            if (not re.fullmatch(r'[A-Za-z0-9_-]+', name) or not isinstance(target, dict)
                    or set(target) != {'deployment', 'deployKeyVariable'}
                    or not isinstance(target['deployment'], str)
                    or not re.fullmatch(r'dev:[a-z0-9]+(?:-[a-z0-9]+)+', target['deployment'])
                    or not isinstance(target['deployKeyVariable'], str)
                    or not re.fullmatch(r'[A-Za-z_][A-Za-z0-9_]*', target['deployKeyVariable'])
                    or target['deployKeyVariable'] in variables):
                raise ValueError('Each additional Convex deployment requires an explicit dev deployment and a unique deployKeyVariable')
            variables.add(target['deployKeyVariable'])
    for key in ("requiredFiles", "localCommands"):
        if not isinstance(dev.get(key), list):
            raise ValueError(f"development.{key} must be an explicit list")
    for name in dev["requiredFiles"]:
        if not isinstance(name, str) or Path(name).is_absolute() or ".." in Path(name).parts:
            raise ValueError("requiredFiles must contain checkout-relative paths")
    # Production pulls and local generation are allowed under the shared policy.
    # Every initializer must be reviewed, idempotent and non-deploying in any environment.
    if dev["localCommands"] and dev["environment"] == "none":
        raise ValueError("Select an environment before enabling localCommands")
    mapping = dev.get("changedTestCommand")
    fields = {"vitest": {"command"}, "pytest": {"command"}, "unittest": {"command"},
              "node-test": {"command"}, "files": {"command", "include"}, "full": {"reason"}}
    if (not isinstance(mapping, dict) or not isinstance(mapping.get("kind"), str)
            or mapping["kind"] not in fields):
        raise ValueError("development.changedTestCommand is required with kind: " + ", ".join(fields))
    required = {"kind", *fields[mapping["kind"]]}
    if not required <= set(mapping) or set(mapping) - required - {"preflight"}:
        raise ValueError("Invalid development.changedTestCommand fields for " + mapping["kind"])
    suite = config['testCommand']
    if not isinstance(suite, list) or not suite or not all(isinstance(arg, str) and arg for arg in suite):
        raise ValueError('testCommand must be a nonempty argv list, with no secrets')
    if mapping["kind"] == "full" and (not isinstance(mapping["reason"], str) or not mapping["reason"].strip()):
        raise ValueError("Full mapping requires a nonempty reason")
    if mapping["kind"] == "files":
        include = mapping["include"]
        if (not isinstance(include, list) or not include or any(
                not isinstance(g, str) or not g or not g.removeprefix("./")
                or Path(g).is_absolute() or ".." in Path(g).parts for g in include)):
            raise ValueError("Files mapping include requires nonempty checkout-relative globs")
        mapping["include"] = [g.removeprefix("./") for g in include]
    if mapping["kind"] == "vitest":
        runner = mapping["command"]
        if (not isinstance(runner, list) or not runner or runner[-1] != "vitest"
                or (config["testCommand"][:len(runner) + 1] != [*runner, "run"]
                    and "preflight" not in mapping)):
            raise ValueError("Vitest mapping command must end in vitest; testCommand must start with that command plus run or declare preflight for a wrapper")
    if (mapping["kind"] == "pytest"
            and mapping["command"] != config["testCommand"]):
        raise ValueError("Pytest mapping command must equal testCommand, including all suite options")
    if mapping["kind"] == "node-test":
        runner = mapping["command"]
        if (not isinstance(runner, list) or len(runner) < 2 or runner[-1] != "--test"
                or config["testCommand"][:len(runner)] != runner
                or any(arg.startswith('-') for arg in config["testCommand"][len(runner):])):
            raise ValueError("Node-test mapping command must end in --test and prefix testCommand; put runner options before --test")
    if mapping["kind"] == "unittest":
        runner = mapping["command"]
        if (not isinstance(runner, list) or len(runner) < 3 or runner[-2:] != ["-m", "unittest"]
                or config["testCommand"][:len(runner) + 1] != [*runner, "discover"]):
            raise ValueError("Unittest mapping must end in -m unittest and testCommand must start with that command plus discover")
    file_checks = dev.get("fileChecks")
    if not isinstance(file_checks, list):
        raise ValueError("development.fileChecks must be an explicit list of per-file checks; use [] for none")
    for check in file_checks:
        include = check.get("include") if isinstance(check, dict) else None
        if (not isinstance(check, dict) or set(check) - {"command", "include", "passFiles", "perFile"}
                or not isinstance(check.get("perFile", False), bool)
                or check.get("perFile") and not check.get("passFiles", True)
                or not isinstance(include, list) or not include
                or any(not isinstance(g, str) or not g or Path(g).is_absolute() or ".." in Path(g).parts for g in include)
                or not isinstance(check.get("passFiles", True), bool)):
            raise ValueError("Each development.fileChecks entry requires command and include globs, with optional passFiles or perFile")
    runner = config.get("ciRunner", "ubuntu-latest")
    if not isinstance(runner, str) or not re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9._-]*", runner):
        raise ValueError("ciRunner must be one GitHub Actions runner label")
    globs = dev.get("sharedInfrastructureGlobs", [])
    if not isinstance(globs, list) or any(
        not isinstance(g, str) or not g or Path(g).is_absolute() or ".." in Path(g).parts
        for g in globs
    ):
        raise ValueError("development.sharedInfrastructureGlobs must contain checkout-relative globs")
    if "sharedInfrastructureGlobs" in dev:
        dev["sharedInfrastructureGlobs"] = [g.removeprefix("./") for g in globs]
    commands = config["validation"] + dev["localCommands"] + [config.get("testCommand")]
    commands = commands + [check["command"] for check in file_checks]
    if "preCommit" in dev:
        commands = commands + [dev["preCommit"]]
    if "command" in mapping:
        commands = commands + [mapping["command"]]
    if "preflight" in mapping:
        commands = commands + [mapping["preflight"]]
    if "dependencies" in dev:
        if not isinstance(dev["dependencies"], dict):
            raise ValueError("development.dependencies must be an object")
        adapter = dev["dependencies"]
        if adapter.get("mode") == "none":
            if set(adapter) != {"mode"}:
                raise ValueError("No-dependencies mode accepts only mode: none")
        else:
            if adapter.get("mode", "locked") != "locked":
                raise ValueError("dependencies.mode must be locked or none")
            commands = commands + [adapter.get("install")]
    for command in commands:
        if not isinstance(command, list) or not command or not all(isinstance(s, str) and s for s in command):
            raise ValueError("Commands must be nonempty argv lists, with no secrets")
        if any(arg in ("--prod", "--run-prod", "deploy") or arg.endswith(":deploy") for arg in command):
            raise ValueError("Setup and validation must not deploy as a side effect")
        for index, argument in enumerate(command[:-1]):
            if Path(argument).name.split('@', 1)[0] != 'convex':
                continue
            operation = command[index + 1:]
            if (operation[0] in ('dev', 'deploy')
                    or operation[:2] in (['deployment', 'create'], ['project', 'create'])
                    or operation[0] == 'run' and '--push' in operation):
                raise ValueError('Setup and validation must not provision Convex deployments or push functions')
    integrations = config["integrations"]
    if not isinstance(integrations.get("greptile"), bool) or not (
        integrations.get("deploymentCheck") is None or isinstance(integrations.get("deploymentCheck"), str)
        and integrations["deploymentCheck"].strip()
    ) or "deploymentCheck" not in integrations:
        raise ValueError("Specify integrations.greptile (boolean) and deploymentCheck (name or null)")
    if not isinstance(config["review"].get("coderabbit"), bool):
        raise ValueError("review.coderabbit must be a boolean")
    if "allowAutoMerge" in config["review"]:
        raise ValueError("Remove obsolete review.allowAutoMerge; native auto-merge is standard")
    checks = config.get("ciChecks")
    if not isinstance(checks, list) or not checks or not all(
        isinstance(c, dict) and isinstance(c.get("context"), str) and c["context"].strip()
        for c in checks
    ):
        raise ValueError("ciChecks must name the repository's actual CI checks")
    declared_tools = dev.get("tools", {})
    if not isinstance(declared_tools, dict) or any(
        not isinstance(k, str) or not k or not isinstance(v, str)
        or not re.fullmatch(r"\d+\.\d+\.\d+", v) for k, v in declared_tools.items()
    ):
        raise ValueError("development.tools must map tool names to exact x.y.z pins")
    ci = config.get("existingCI")
    if ci is not None:
        if (not isinstance(ci, dict) or set(ci) != {"workflow", "job", "context"}
                or not all(isinstance(v, str) and v for v in ci.values())
                or not re.fullmatch(r"\.github/workflows/[A-Za-z0-9_.-]+\.ya?ml", ci["workflow"])
                or not re.fullmatch(r"[A-Za-z_][A-Za-z0-9_-]*", ci["job"])
                or ci["context"] not in [c["context"] for c in checks]):
            raise ValueError("existingCI requires workflow, job and a context listed in ciChecks")
    check_facts(config)
    return config


def run(command, root=ROOT):
    # Child output can contain environment values. Never echo it or argv on failure.
    result = subprocess.run(command, cwd=root, capture_output=True, text=True,
                            env={**os.environ, "MISE_AUTO_INSTALL": "0"})
    if result.returncode:
        raise RuntimeError(f"{Path(command[0]).name} failed (exit {result.returncode}); inspect locally with secret-safe logging")
    return result.stdout.strip()


def validate_services(root, config):
    if (Path(root) / 'convex').is_dir() and 'convex' not in config['development']:
        raise ValueError('Configuration drift: convex/ requires development.convex with a shared dev deployment')


def toolchain(root, config=None):
    if not (root / "mise.toml").is_file():
        raise ValueError("Missing mise.toml; adopt the repository tool configuration before setup")
    tools = tomllib.loads((root / "mise.toml").read_text()).get("tools", {})
    if not isinstance(tools, dict) or any(not isinstance(v, str) or not re.fullmatch(r"\d+\.\d+\.\d+", v) for v in tools.values()):
        raise ValueError("Pin every mise.toml tool to an exact x.y.z version")
    config = config or read_config(root / ".repo-standard.json")
    if config["development"].get("dependencies", {}).get("mode") == "none":
        package_file = root / "package.json"
        if package_file.exists():
            package_data = json.loads(package_file.read_text())
            if not isinstance(package_data, dict):
                raise ValueError("package.json must contain an object")
            fields = ("dependencies", "devDependencies", "optionalDependencies")
            if any(not isinstance(package_data.get(key, {}), dict) for key in fields):
                raise ValueError("Package dependency fields must be objects")
            if any(package_data.get(key) for key in fields):
                raise ValueError("No-dependencies mode conflicts with declared package dependencies")
        return tools, []
    if not tools:
        raise ValueError("Locked dependency installs require exact mise tool pins")
    package = root / "package.json"
    if not package.exists():
        config = config or read_config(root / ".repo-standard.json")
        adapter = config["development"].get("dependencies")
        if not isinstance(adapter, dict):
            raise ValueError("Non-Node stacks require development.dependencies with lockfile, install and artifacts")
        install = adapter.get("install")
        if not isinstance(install, list) or not install or not all(isinstance(s, str) and s for s in install):
            raise ValueError("dependencies.install must be a locked-install argv list")
        paths = [adapter.get("lockfile")] + adapter.get("artifacts", [])
        if not adapter.get("artifacts") or any(not isinstance(p, str) or not p or Path(p).is_absolute() or ".." in Path(p).parts for p in paths):
            raise ValueError("dependencies lockfile and artifacts must be nonempty checkout-relative paths")
        if not (root / adapter["lockfile"]).is_file():
            raise ValueError("Missing adapter lockfile; commit it before setup")
        return tools, install
    manager = json.loads(package.read_text()).get("packageManager", "")
    match = re.fullmatch(r"(pnpm|npm|yarn)@(\d+\.\d+\.\d+)(?:\+sha\d+\..+)?", manager)
    if not match or "node" not in tools:
        raise ValueError("Declare node in mise.toml and pinned pnpm, npm or Yarn in package.json.packageManager")
    name, version = match.groups()
    if tools.get(name) != version:
        raise ValueError(f"Pin {name}={version} in mise.toml to match packageManager")
    installs = {"pnpm": ("pnpm-lock.yaml", ["pnpm", "install", "--frozen-lockfile"]),
                "npm": ("package-lock.json", ["npm", "ci"]),
                "yarn": ("yarn.lock", ["yarn", "install", "--immutable"])}
    if name == "yarn" and int(version.split(".")[0]) < 2:
        raise ValueError("Yarn requires version 2+ for immutable installs")
    lock, install = installs[name]
    if not (root / lock).is_file():
        raise ValueError(f"Missing {lock}; commit a lockfile before provisioning")
    return tools, install


def tool_version(output):
    match = re.search(r'\b(?:go|v)?(\d+\.\d+\.\d+)\b', output)
    if not match:
        raise ValueError('Tool returned no semantic version; document a supported version adapter')
    return match.group(1)


def provision(root, doctor=False, *, ci=False):
    config = read_config(root / ".repo-standard.json")
    validate_services(root, config)
    tools, install = toolchain(root, config)
    for executable in ("git", "mise"):
        if not shutil.which(executable):
            raise ValueError(f"Install {executable} on the host first")
    if Path(run(["git", "rev-parse", "--show-toplevel"], root)).resolve() != root:
        raise ValueError("Setup script must live in the checkout it provisions")
    dev = config["development"]
    hooks = subprocess.run(["git", "config", "--get", "core.hooksPath"], cwd=root, capture_output=True, text=True)
    if hooks.stdout.strip() not in ("", ".githooks"):
        raise ValueError("Existing core.hooksPath differs; integrate hooks manually before setup")
    for hook in ("pre-commit", "pre-push"):
        if not (root / ".githooks" / hook).is_file():
            raise ValueError(f"Missing .githooks/{hook}; adopt the hooks before setup")
    # Check selection and artifacts before any command, including dependency scripts.
    missing = [p for p in dev["requiredFiles"] if not (root / p).is_file()
               and not (p == '.env.local' and 'vercel' in dev and not doctor)]
    if missing and not ci:
        raise ValueError("Required local artifacts missing; pull the selected environment from its cloud store: " + ", ".join(missing))
    if not doctor:
        print("Installing pinned tools and locked dependencies", flush=True)
        run(["mise", "install"], root)
    for name, expected in tools.items():
        short = name.split(':')[-1].split('/')[-1]
        probe = VERSION_PROBES.get(short, [short, '--version'])
        output = run(['mise', 'exec', '--', *probe], root)
        if not output:
            raise ValueError(f"{name} returned no version; check the installed tool")
        actual = tool_version(output)
        if actual != expected:
            raise ValueError(f"{name} version mismatch; run mise install in this checkout")
    if doctor:
        if not install:
            missing = False
        elif (root / "package.json").exists():
            missing = not (root / "node_modules").is_dir() and not (root / ".pnp.cjs").is_file()
        else:
            missing = any(not (root / p).exists() for p in dev["dependencies"]["artifacts"])
        if missing:
            raise ValueError("Dependencies missing; run ./scripts/setup")
        result = subprocess.run(["git", "config", "--get", "core.hooksPath"], cwd=root, capture_output=True, text=True)
        if result.stdout.strip() != ".githooks":
            raise ValueError("Hooks missing; run ./scripts/setup")
    else:
        if install:
            run(["mise", "exec", "--", *install], root)
        run(["git", "config", "core.hooksPath", ".githooks"], root)

    if ci:
        print('CI tools, locked dependencies and hooks ready. Run ./scripts/check.')
        return
    if 'vercel' in dev:
        from service_setup import prepare
        prepare(root, dev, doctor=doctor)
    if not doctor:
        for command in dev["localCommands"]:
            run(["mise", "exec", "--", *command], root)

    if doctor:
        from pre_push import repository_checks
        for check in repository_checks(root, '.githooks/doctor.d'):
            run([str(check)], root)
    if doctor:
        print("Local configuration, tools, dependency presence and hooks verified; no provisioning performed.")
        print("Cloud credentials and dependency freshness are not certified by doctor.")
    else:
        print("Checkout ready. Start development separately; AGENTS.md lists the commands.")

